(
  /* Get tenant timezone (default to America/Detroit if not available) */
  $timezone := $.setting.edges.node.defaultValue ? $.setting.edges.node.defaultValue : $momentTzGuess();
  
  /* Calculate yesterday in LOCAL timezone, then convert to UTC */
  $yesterdayStartLocal := $moment().tz($timezone).subtract(1, 'day').startOf('day');
  $yesterdayEndLocal := $moment().tz($timezone).subtract(1, 'day').endOf('day');
  
  /* Convert to UTC for database query */
  {
    "recordedAtStart": $moment($yesterdayStartLocal),
    "recordedAtEnd": $moment($yesterdayEndLocal),
    "localDate": $moment($yesterdayStartLocal).format("YYYY-MM-DD"),
    "timezone": $timezone
  }
)

data.query:
query GetTimezoneAndWorkcenters {
  setting(where: { id: { _eq: "TimeZone" } }) {
    edges {
      node {
        defaultValue
      }
    }
  }
}

