// ============================================================

var totalCount = 0;
var totalCountGood = 0;
var totalCountBad = 0;
var totalCountTrue = 0;
var totalCountFalse = 0;
var totalSum = 0;

for (var i = 0; i < hourlyRecords.length; i++) {
  var hr = hourlyRecords[i];
  totalCount += hr.count || 0;
  totalCountGood += hr.countGood || 0;
  totalCountBad += hr.countBad || 0;
  totalCountTrue += hr.countTrue || 0;
  totalCountFalse += hr.countFalse || 0;
  totalSum += hr.sum || 0;
}

console.log('Total count: ' + totalCount);

// ============================================================
// AGGREGATE MIN/MAX/FIRST/LAST
// ============================================================

var dailyMin = null;
var dailyMax = null;
var dailyFirst = null;
var dailyLast = null;

for (var i = 0; i < hourlyRecords.length; i++) {
  var hr = hourlyRecords[i];
  
  // Min
  if (hr.min != null) {
    if (dailyMin === null || hr.min < dailyMin) {
      dailyMin = hr.min;
    }
  }
  
  // Max
  if (hr.max != null) {
    if (dailyMax === null || hr.max > dailyMax) {
      dailyMax = hr.max;
    }
  }
  
  // First (from earliest hour)
  if (i === 0 && hr.first != null) {
    dailyFirst = hr.first;
  }
  
  // Last (from latest hour)
  if (i === hourlyRecords.length - 1 && hr.last != null) {
    dailyLast = hr.last;
  }
}

// ============================================================
// CALCULATE AVERAGE
// ============================================================

var dailyAvg = totalCount > 0 ? totalSum / totalCount : 0;

// ============================================================
// CALCULATE POOLED STANDARD DEVIATION
// ============================================================

var varianceSum = 0;
var validStdCount = 0;

for (var i = 0; i < hourlyRecords.length; i++) {
  var hr = hourlyRecords[i];
  if (hr.std != null && hr.count > 0) {
    // Variance = std^2
    var hourlyVariance = hr.std * hr.std;
    // Weighted by count
    varianceSum += hourlyVariance * hr.count;
    validStdCount += hr.count;
  }
}

var dailyStd = validStdCount > 0 ? Math.sqrt(varianceSum / validStdCount) : 0;

// ============================================================
