// ============================================================

var dailyRange = (dailyMin != null && dailyMax != null) ? dailyMax - dailyMin : 0;
var dailyCv = dailyAvg !== 0 ? Math.abs(dailyStd / dailyAvg) : 0;
var dailyPctTrue = totalCount > 0 ? (totalCountTrue / totalCount) * 100 : 0;

// ============================================================
// AGGREGATE PERCENTILES (WEIGHTED AVERAGE APPROXIMATION)
// ============================================================

var p05Sum = 0, p25Sum = 0, p50Sum = 0, p75Sum = 0, p95Sum = 0;
var pCount = 0;

for (var i = 0; i < hourlyRecords.length; i++) {
  var hr = hourlyRecords[i];
  var weight = hr.count || 0;
  
  if (weight > 0) {
    p05Sum += (hr.p05 || 0) * weight;
    p25Sum += (hr.p25 || 0) * weight;
    p50Sum += (hr.p50 || 0) * weight;
    p75Sum += (hr.p75 || 0) * weight;
    p95Sum += (hr.p95 || 0) * weight;
    pCount += weight;
  }
}

var dailyP05 = pCount > 0 ? p05Sum / pCount : 0;
var dailyP25 = pCount > 0 ? p25Sum / pCount : 0;
var dailyP50 = pCount > 0 ? p50Sum / pCount : 0;
var dailyP75 = pCount > 0 ? p75Sum / pCount : 0;
var dailyP95 = pCount > 0 ? p95Sum / pCount : 0;

// ============================================================
// AGGREGATE DISTINCT COUNT (MAX APPROXIMATION)
// ============================================================

var dailyDistinctCount = 0;
for (var i = 0; i < hourlyRecords.length; i++) {
  var hr = hourlyRecords[i];
  if (hr.distinctCount != null && hr.distinctCount > dailyDistinctCount) {
    dailyDistinctCount = hr.distinctCount;
  }
