// ============================================================
// AGGREGATE MODE (MOST FREQUENT VALUE)
// ============================================================

var modeMap = {};
for (var i = 0; i < hourlyRecords.length; i++) {
  var hr = hourlyRecords[i];
  if (hr.modeValue != null && hr.modeCount != null) {
    if (!modeMap[hr.modeValue]) {
      modeMap[hr.modeValue] = 0;
    }
    modeMap[hr.modeValue] += hr.modeCount;
  }
}

var dailyModeValue = null;
var dailyModeCount = 0;

for (var value in modeMap) {
  if (modeMap[value] > dailyModeCount) {
    dailyModeValue = value;
    dailyModeCount = modeMap[value];
  }
}

// ============================================================
// BUILD OUTPUT RECORD
// ============================================================

var dailyRecord = {
  id: dailyId,
  dataPointId: dataPointId,
  periodAt: periodAt,
  count: totalCount,
  countGood: totalCountGood,
  countBad: totalCountBad,
  countTrue: totalCountTrue,
  countFalse: totalCountFalse,
  min: dailyMin,
  max: dailyMax,
  avg: dailyAvg,
  sum: totalSum,
  std: dailyStd,
  first: dailyFirst,
  last: dailyLast,
  range: dailyRange,
  cv: dailyCv,
  pctTrue: dailyPctTrue,
  p05: dailyP05,
  p25: dailyP25,
  p50: dailyP50,
  p75: dailyP75,
  p95: dailyP95,
  distinctCount: dailyDistinctCount,
  modeValue: dailyModeValue,
  modeCount: dailyModeCount
};

console.log('Daily aggregation complete');
console.log('ID: ' + dailyId);
console.log('Min: ' + dailyMin + ' | Max: ' + dailyMax + ' | Avg: ' + dailyAvg.toFixed(2));
console.log('Std: ' + dailyStd.toFixed(2) + ' | CV: ' + dailyCv.toFixed(4));
console.log('=== END DAILY AGGREGATION ===');

return dailyRecord;

